"""Forty-four independently authored applications; task conventions, not copied items.

Research settings and literary scenes are hypothetical original stimuli. Intended
cognitive demands are provisional, and every case requires independent review.
"""
from english_common import make_item


def bp(skill, method, formula, structure, misconceptions):
    return dict(skill=skill, method=method, formula=formula, structure=structure,
                misconceptions=misconceptions, variants=4)


